def collect(fetch):
    result, cursor, seen = [], None, set()
    for _ in range(100):
        page, cursor = fetch(cursor)
        result.extend(page)
        if cursor is None: return result
        if cursor in seen: raise ValueError("repeated cursor")
        seen.add(cursor)
    raise ValueError("page bound exceeded")

