from threading import Lock
from copy import deepcopy
class Ledger:
    def __init__(self): self.rows={}; self.lock=Lock()
    def append(self,key,value):
        with self.lock:
            if key in self.rows:
                seq,old=self.rows[key]
                if old != value: raise ValueError("conflicting value")
                return seq
            seq=len(self.rows)+1
            self.rows[key]=(seq,deepcopy(value))
            return seq
